package flags

func lokiCases() {
	lokiCase("c1", "change", "FlagLine with short alias from the issue", func() any {
		return FlagLine(Flag{Name: "output", Short: "o", Usage: "write to file"})
	})
	lokiCase("c2", "change", "FlagLine with short alias and default", func() any {
		return FlagLine(Flag{Name: "output", Short: "o", Usage: "write to file", Default: "out.txt"})
	})
	lokiCase("c3", "change", "Help listing containing a flag with a short alias", func() any {
		return Help("tool", []Flag{{Name: "output", Short: "o", Usage: "write to file"}})
	})

	lokiCase("k1", "keep", "FlagLine for flag without short alias from the issue", func() any {
		return FlagLine(Flag{Name: "verbose", Usage: "print more"})
	})
	lokiCase("k2", "keep", "FlagLine without short alias but with default", func() any {
		return FlagLine(Flag{Name: "verbose", Usage: "print more", Default: "false"})
	})
	lokiCase("k3", "keep", "names() for flag with short alias keeps long-first order", func() any {
		return names(Flag{Name: "output", Short: "o"})
	})
	lokiCase("k4", "keep", "names() for flag without short alias", func() any {
		return names(Flag{Name: "verbose"})
	})
	lokiCase("k5", "keep", "MissingError message for flag with short alias", func() any {
		return MissingError(Flag{Name: "output", Short: "o"}).Error()
	})
	lokiCase("k6", "keep", "MissingError message for flag without short alias", func() any {
		return MissingError(Flag{Name: "verbose"}).Error()
	})
	lokiCase("k7", "keep", "Lookup by short name -o", func() any {
		fs := []Flag{{Name: "output", Short: "o"}}
		return lokiAll(Lookup(fs, "-o"))
	})
	lokiCase("k8", "keep", "Lookup with uppercase short name -O fails", func() any {
		fs := []Flag{{Name: "output", Short: "o"}}
		return lokiAll(Lookup(fs, "-O"))
	})
	lokiCase("k9", "keep", "Lookup with leading whitespace fails", func() any {
		fs := []Flag{{Name: "output", Short: "o"}}
		return lokiAll(Lookup(fs, " -o"))
	})
	lokiCase("k10", "keep", "Help listing for flag without short alias", func() any {
		return Help("tool", []Flag{{Name: "verbose", Usage: "print more"}})
	})
	lokiCase("k11", "keep", "Help with empty program name and no flags", func() any {
		return Help("", nil)
	})
	lokiCase("k12", "keep", "Lookup unknown flag error", func() any {
		fs := []Flag{{Name: "output", Short: "o"}}
		return lokiAll(Lookup(fs, "--nope"))
	})
}
